# Quick-quiz question bank for FTX4087S Topics in Banking and Treasury Management (UCT).
# Short type-in questions on theory and application. These are NOT copies of past-paper questions.
# Sources: the 2026 course slides and the three course notes PDFs (Intro to Banking & Treasury,
# Bank Regulation & Failure, Risk Management for Banks). Figures in calculations are invented.
#
# Each entry is (question, model answer, check):
#   check = a number          -> the typed answer is marked right if it is that number
#   check = a regex (string)  -> marked right if the typed answer matches it (case-insensitive)
#   check = [regex, regex]    -> marked right only if every regex matches
# Percent answers are typed as the percent number (12.5 for 12.5%).
# The student can always override the automatic mark after seeing the model answer.

NO = r"\bno\b|\bnot\b|cannot|can't|\bnil\b|\bnone\b"
YES = r"\byes\b"

